import pandas as pd

def run(inputs: dict) -> dict:
    hist = inputs["dim_emp_hist"]
    queries = inputs["asof_queries"]

    merged = queries.merge(hist, on="emp_id", how="inner", suffixes=("", "_h"))

    cond = (merged["as_of_date"] >= merged["eff_start_date"]) & (
        merged["eff_end_date"].isna() | (merged["as_of_date"] < merged["eff_end_date"])
    )

    result = merged.loc[cond, ["query_id", "emp_id", "dept", "grade"]].reset_index(drop=True)

    return {"asof_result": result}
